      allSchemaEntities.whereType<TableInfo<Table, Object?>>();
  @override
  List<DatabaseSchemaEntity> get allSchemaEntities =>
      [accounts, favorites, localSubscriptions];
  @override
  int get schemaVersion => 1;
}
